function contactInfoValue(c,key){if(key==='remark')return c.remark||'';if(key==='phone')return c.phone||'';if(key==='tags')return Array.isArray(c.tags)?c.tags.join('、'):(c.tags||'');if(key==='note')return c.note||'';if(key==='signature')return c.signature||'';return'';}
function contactFieldEdit(id,key,label){const c=getC(id),allowed=['remark','phone','tags','note','signature'];if(!c||!allowed.includes(key))return;const value=contactInfoValue(c,key),multi=key==='note';openModal(`<h3>${esc(label)}</h3><div class="field">${multi?`<textarea id="contact_field_value" rows="5">${esc(value)}</textarea>`:`<input id="contact_field_value" value="${esc(value)}" placeholder="填写${esc(label)}">`}</div><div class="btns"><button class="btn g" onclick="closeModal()">取消</button><button class="btn p" onclick="contactFieldSave('${id}','${key}')">保存</button></div>`);}
function contactFieldSave(id,key){const c=getC(id),el=$('#contact_field_value');if(!c||!el)return;const v=el.value.trim();if(key==='tags')c.tags=v.split(/[、,，]/).map(x=>x.trim()).filter(Boolean).slice(0,12);else c[key]=v;save();closeModal();render();toast('已保存');}
