/* CONTACT_PHOTO_DEL_V1（2026-10-18 她发现朋友资料里的照片删不掉）：每张右上角一个 ✕，确认后删掉这一张 */
async function contactPhotoDel(id,i){const c=getC(id);if(!c||!Array.isArray(c.profilePhotos)||!c.profilePhotos[i])return;if(!await uiConfirm('删除这张照片？',{danger:true,yes:'删除'}))return;c.profilePhotos.splice(i,1);save();contactPhotosOpen(id);render();toast('已删除');}
function contactPhotoAdd(id){pickFile('image/*',async f=>{const c=getC(id);if(!c)return;c.profilePhotos=Array.isArray(c.profilePhotos)?c.profilePhotos:[];c.profilePhotos.unshift(await compress(f,900,.72));c.profilePhotos=c.profilePhotos.slice(0,12);save();contactPhotosOpen(id);});}
function roleImageStudioThumb(src,label){src=String(src||'');const ready=isStoredImgRef(src)?(_imgCache[src.slice(4)]||''):src;return ready?`<img src="${ready}" alt="${esc(label||'参考图')}" style="width:72px;height:92px;object-fit:cover;border-radius:10px">`:`<span style="width:72px;height:92px;border-radius:10px;background:#242428;display:grid;place-items:center;color:#777;font-size:12px">图片加载中</span>`;}
function roleImageStudioWardrobeThumb(src,label){src=String(src||'');const ready=isStoredImgRef(src)?(_imgCache[src.slice(4)]||''):src;return ready?`<img src="${ready}" alt="${esc(label||'衣物参考')}" loading="lazy" decoding="async" style="display:block;width:100%;aspect-ratio:4/5;object-fit:cover;background:#242428">`:`<span style="width:100%;aspect-ratio:4/5;background:#242428;display:grid;place-items:center;color:#777;font-size:12px">图片加载中</span>`;}
function roleImageOccasionLabel(key){const row=ROLE_IMAGE_OCCASIONS.find(x=>x[0]===key);return row?row[1]:'外出日常';}
function roleImageStudioCapture(id){const c=roleImageStudioOwner(id),st=roleImageStudio(c,true);if(!c||!st)return null;const enabled=$('#ris_enabled'),face=$('#ris_face'),prompt=$('#ris_prompt'),note=$('#ris_identity_note');if(enabled)st.enabled=enabled.classList.contains('on');if(face)st.faceMode=face.value==='allowed'?'allowed':'hidden';if(prompt)st.appearancePrompt=prompt.value.trim().slice(0,1200);if(note)st.identityNote=note.value.trim().slice(0,1000);const gender=$('#ris_gender');if(c._userImageStudio&&gender)st.gender=['男','女'].includes(gender.value)?gender.value:'';return st;}
function roleImageStudioSave(id,quiet){const c=roleImageStudioOwner(id),st=roleImageStudioCapture(id);if(!c||!st)return false;save();render();if(!quiet)toast(c._userImageStudio?'我的形象设置已保存':'角色形象设置已保存');return true;}
