function renderRoleImageStudio(id){const c=roleImageStudioOwner(id);if(!c)return'';const st=roleImageStudio(c,true),faces=st.identityRefs.map(ref=>`<article style="position:relative;min-width:0;overflow:hidden;background:#19191c;border:1px solid #29292d;border-radius:14px"><button type="button" onclick="roleImageStudioFaceActions('${id}','${ref.id}')" style="display:block;width:100%;padding:0;border:0;background:transparent;color:inherit;text-align:left">${roleImageStudioWardrobeThumb(ref.image,roleImageStudioFaceLabel(ref.angle))}<span style="display:block;padding:9px 10px 10px;min-width:0"><b style="display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:14px">${roleImageStudioFaceLabel(ref.angle)}</b><small style="display:block;color:#d0aa79;margin-top:4px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">固定人物 · 已保存</small></span></button><button type="button" aria-label="面部参考操作" onclick="event.stopPropagation();roleImageStudioFaceActions('${id}','${ref.id}')" style="position:absolute;right:7px;top:7px;width:30px;height:30px;padding:0;border:0;border-radius:15px;background:rgba(20,20,22,.78);color:#fff;font-size:18px;line-height:1">···</button></article>`).join(''),outfits=st.outfits.map(row=>`<article style="position:relative;min-width:0;overflow:hidden;background:#19191c;border:1px solid #29292d;border-radius:14px;opacity:${row.enabled!==false?'1':'.55'}"><button type="button" onclick="roleImageStudioOutfitEdit('${id}','${row.id}')" style="display:block;width:100%;padding:0;border:0;background:transparent;color:inherit;text-align:left">${roleImageStudioWardrobeThumb(row.image,row.name)}<span style="display:block;padding:9px 10px 10px;min-width:0"><b style="display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:14px">${esc(row.name)}</b><small style="display:block;color:#d0aa79;margin-top:4px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(roleImageOccasionLabel(row.occasion))}${roleImageTimeRangeLabel(row)?' · '+esc(roleImageTimeRangeLabel(row)):''}${row.enabled===false?' · 已停用':''}</small></span></button><button type="button" aria-label="衣物操作" onclick="event.stopPropagation();roleImageStudioOutfitActions('${id}','${row.id}')" style="position:absolute;right:7px;top:7px;width:30px;height:30px;padding:0;border:0;border-radius:15px;background:rgba(20,20,22,.78);color:#fff;font-size:18px;line-height:1">···</button></article>`).join('');
  return `<div class="wx-subpage"><div class="wx-real-nav titled"><button onclick="back()">‹</button><b>${c._userImageStudio?'我的形象工作室':'角色形象工作室'}</b><button onclick="roleImageStudioSave('${id}')" style="font-size:14px;width:auto">保存</button></div><div class="wx-real-scroll wx-info-scroll" style="padding-bottom:32px"><div role="note" style="margin:12px 12px 4px;padding:10px 12px;border:1px solid rgba(255,69,69,.42);border-radius:10px;background:rgba(255,69,69,.08);color:#ff4d4f;font-size:13px;font-weight:700;line-height:1.5">未经允许不可侵犯他人肖像权，后果自负。</div><div class="wx-info-label">自定义生成</div><div class="wx-info-group"><button type="button" onclick="$('#ris_enabled').classList.toggle('on')"><span>使用自定义${c._userImageStudio?'本人':'角色'}形象<small style="display:block;color:#888;margin-top:3px">${c._userImageStudio?'开启后在你需要入镜时使用你的形象；关闭恢复原逻辑':'开启后替代旧的角色外观提示词；关闭可随时恢复原逻辑'}</small></span><i id="ris_enabled" class="wx-switch ${st.enabled?'on':''}"></i></button></div><div class="wx-info-group" style="padding:12px">${c._userImageStudio?'<label>本人性别（选填）<select id="ris_gender" style="display:block;width:100%;box-sizing:border-box;margin:7px 0 12px;padding:10px;border:1px solid #333;border-radius:10px;background:#171719;color:#eee"><option value="">按本人说明与参考，不猜测</option><option value="男" '+(st.gender==='男'?'selected':'')+'>男</option><option value="女" '+(st.gender==='女'?'selected':'')+'>女</option></select></label>':''}<label style="display:block;width:100%"><span style="display:block;margin-bottom:7px">人物生成要求</span><textarea id="ris_prompt" rows="5" placeholder="${c._userImageStudio?'例如：自己的发型、肤色、体型，以及需要保留的外观特征':'例如：三十岁成年男性，黑色大背头梳理整齐，发丝不散乱，肩宽，冷白肤色，日常照片自然克制'}" style="width:100%;box-sizing:border-box;border:1px solid #333;border-radius:10px;background:#171719;color:#eee;padding:10px">${esc(st.appearancePrompt)}</textarea></label><label style="display:block;width:100%;margin-top:12px"><span style="display:block;margin-bottom:7px">露脸方式</span><select id="ris_face" style="width:100%;border:1px solid #333;border-radius:10px;background:#171719;color:#eee;padding:10px"><option value="hidden" ${st.faceMode!=='allowed'?'selected':''}>不允许生成可见脸</option><option value="allowed" ${st.faceMode==='allowed'?'selected':''}>有身份参考时允许露脸</option></select><small style="display:block;color:#888;margin-top:6px;line-height:1.5">没有上传正面或侧面身份参考时，即使选了允许露脸，也会自动按“不允许露脸”执行，避免随机换脸。</small></label></div>
    <div class="wx-info-label">固定脸 · 可上传多个角度</div><div style="display:grid;gap:8px;padding:0 12px"><div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px">${faces||'<div class="empty" style="grid-column:1/-1;padding:18px">还没有身份参考；当前不会生成可见脸</div>'}</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px"><button class="btn g" onclick="roleImageStudioFaceUpload('${id}','front')">上传正面</button><button class="btn g" onclick="roleImageStudioFaceUpload('${id}','side')">上传侧面</button></div><label style="display:block"><span style="display:block;margin:10px 0 6px">固定脸补充说明</span><textarea id="ris_identity_note" rows="3" placeholder="可补充脸型、发际线、眉眼、鼻唇和必须保持的辨识特征" style="width:100%;box-sizing:border-box;border:1px solid #333;border-radius:10px;background:#171719;color:#eee;padding:10px">${esc(st.identityNote)}</textarea></label></div>
    <div class="wx-info-label">${c._userImageStudio?'我的衣柜':'角色衣柜'}</div><div style="padding:0 12px"><div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px">${outfits||'<div class="empty" style="grid-column:1/-1;padding:18px">还没有衣物参考</div>'}</div><button class="btn p" style="width:100%;margin-top:10px" onclick="roleImageStudioOutfitUpload('${id}')">＋ 上传一件衣物</button><small style="display:block;color:#888;line-height:1.55;margin-top:8px">每套衣服都能设置精确的开始和结束时间；当前时间命中时只从命中的衣服里挑，并优先匹配场景。未开启时间固定的衣服继续按原来的场景随机逻辑选择。</small></div>
    <div class="wx-info-label">测试生成</div><div class="wx-info-group" style="padding:12px"><label style="display:block;width:100%"><span style="display:block;margin-bottom:7px">这次想测试什么</span><textarea id="ris_test" rows="3" placeholder="例如：他刚下班回到家，在客厅随手拍一张半身照；或：他正在工作室整理文件" style="width:100%;box-sizing:border-box;border:1px solid #333;border-radius:10px;background:#171719;color:#eee;padding:10px"></textarea></label><button class="btn p" style="width:100%;margin-top:10px" onclick="roleImageStudioTest('${id}')">生成一张测试预览</button><small style="display:block;color:#888;margin-top:7px;line-height:1.5">测试会真实调用当前图片接口并可能产生费用，但图片只在预览里显示，不会发送到微信或朋友圈。</small></div></div></div>`;}
async function roleImageStudioDescribe(src,kind){try{return await visionAPI(src,kind==='face'?'只描述图中主要成年人物可稳定复用的身份外观：脸型、发际线、发型和梳理方向、发色、眉眼、鼻唇、肤色、年龄感、体型及明显辨识特征。不要描述背景、动作和衣服，不猜身份，不评价好看与否。':'只描述这件衣物或配饰可用于图像生成的视觉特征：准确类别、主辅颜色、版型剪裁、领口袖型、长度、面料质感、图案、配件和穿着轮廓。不要描述人物脸和背景。',{primaryOnly:false});}catch(_){return'';}}
function roleImageStudioFaceLabel(angle){return angle==='front'?'正面参考':angle==='side'?'侧面参考':angle==='three-quarter'?'四分之三侧面':'其他角度';}
function roleImageStudioFaceActions(id,rid){const c=roleImageStudioOwner(id),st=roleImageStudioCapture(id),row=st&&st.identityRefs.find(x=>x.id===rid);if(!c||!row)return;openModal(`<h3>${roleImageStudioFaceLabel(row.angle)}</h3><div style="max-width:220px;margin:8px auto 12px">${roleImageStudioWardrobeThumb(row.image,roleImageStudioFaceLabel(row.angle))}</div><div class="hint">这张图片会作为固定人物身份参考，识别长文已收起，不会再占满工作室页面。</div>${row.note?`<details style="margin:12px 0"><summary style="cursor:pointer;color:#d0aa79">查看识别详情</summary><div style="margin-top:8px;padding:10px;border-radius:10px;background:#19191c;color:#aaa;line-height:1.55;max-height:180px;overflow:auto">${esc(row.note)}</div></details>`:''}<div class="btns"><button class="btn g" onclick="closeModal()">完成</button><button class="btn r" onclick="closeModal();roleImageStudioFaceDelete('${id}','${rid}')">删除参考</button></div>`);}
function roleImageStudioFaceUpload(id,angle){roleImageStudioCapture(id);pickFile('image/*',async f=>{const c=roleImageStudioOwner(id),st=roleImageStudio(c,true);if(!c||!st)return;aiLoad('正在保存并理解身份参考…');try{const src=await compress(f,1200,.86);if(roleImageStudioOwner(id)!==c)return;try{await primeImageForSave(src);}catch(_){}const note=await roleImageStudioDescribe(src,'face');if(roleImageStudioOwner(id)!==c)return;const old=st.identityRefs.find(x=>x.angle===angle),row={id:old&&old.id||uid(),angle,image:src,note:note.slice(0,800)};const previous=st.identityRefs.slice();st.identityRefs=st.identityRefs.filter(x=>x.angle!==angle);st.identityRefs.push(row);if((await saveNowAsync())===false){st.identityRefs=previous;toast('身份参考没有写入本机，请检查存储后重试');return;}toast((angle==='front'?'正面':'侧面')+'身份参考已保存');render();}finally{aiDone();}});}
async function roleImageStudioFaceDelete(id,rid){const c=roleImageStudioOwner(id),st=roleImageStudioCapture(id);if(!c||!st)return;if(!await uiConfirm('删除这张身份参考？'))return;st.identityRefs=st.identityRefs.filter(x=>x.id!==rid);save();render();}
let _roleImageOutfitDraft=null;
function roleImageStudioOutfitReadTimeRange(){const on=$('#rio_time_fixed'),start=$('#rio_time_start'),end=$('#rio_time_end');return{enabled:!!(on&&on.checked),start:String(start&&start.value||''),end:String(end&&end.value||'')};}
